  function update() {
    $('#cashValue').textContent=fmt(state.cash); $('#chartBalance').textContent=fmt(state.cash + state.games.length*8500);
    $('#revenueValue').textContent=fmt(state.revenue); $('#teamValue').textContent=state.team.length;
