  function hire(role){const roster={Designer:{salary:90,skill:6,initials:'DS'},Programmer:{salary:120,skill:7,initials:'PG'},Artist:{salary:85,skill:6,initials:'AR'},Producer:{salary:105,skill:6,initials:'PR'},Marketer:{salary:95,skill:5,initials:'MK'}};const r=roster[role];if(!r)return;const cost=r.salary*7;if(state.cash<cost){notify(`Hiring bonus requires ${fmt(cost)}.`,'＄');return;}const first=['Sam','Alex','Taylor','Casey','Jordan','Cameron','Robin','Drew'][Math.floor(Math.random()*8)];const last=['Park','Reed','Stone','Rivera','Bell','Nguyen','Brooks','Wells'][Math.floor(Math.random()*8)];state.cash-=cost;state.team.push({name:`${first} ${last}`,role,skill:r.skill,salary:r.salary,initials:r.initials});state.reputation=Math.min(100,state.reputation+1);log('♧','green',`<strong>${escapeHtml(first)} ${escapeHtml(last)}</strong> joined as a ${role.toLowerCase()}.`);update();notify(`${first} joined your studio. Welcome aboard!`);navigate('team');}
  function upgradeOffice(){const cost=state.officeLevel===1?8500:state.officeLevel===2?22000:45000;if(state.officeLevel>=4){notify('Your studio is already at its biggest!');return;}if(state.cash<cost){notify(`Office upgrade costs ${fmt(cost)}.`,'＄');return;}state.cash-=cost;state.officeLevel++;state.reputation=Math.min(100,state.reputation+3);log('⌂','blue',`Your studio moved into a bigger office. Welcome to <strong>Level ${state.officeLevel}</strong>!`);update();notify('A bigger office — room for bigger dreams!');navigate('office');}
  function campaign(){const cost=2500;if(state.cash<cost){notify('Not enough cash for a campaign.','＄');return;}state.cash-=cost;state.marketing+=500;state.reputation=Math.min(100,state.reputation+4);state.competitors.forEach(c=>c.share=Math.max(8,c.share-2));log('↗','yellow',`A community campaign is bringing new fans to <strong>${escapeHtml(state.project?.name||'your studio')}</strong>.`);update();notify('Campaign launched! Your reputation is up.');navigate('market');}

  const projectsView=()=>`<div class="view-heading"><div><div class="eyebrow">MAKE SOMETHING MEMORABLE</div><h1>Your projects</h1><p>Dream up a new game, then bring it to life with your team.</p></div><span class="card-tag">${state.games.length} RELEASED</span></div>${state.project?`<div class="wide-panel"><h2>Currently in development</h2><div class="employee-row"><div class="card-icon">◈</div><div class="employee-info"><strong>${escapeHtml(state.project.name)} · ${state.project.progress}% complete</strong><small>${escapeHtml(state.project.genre)} · ${escapeHtml(state.project.platform)} · ${state.project.phase}</small></div><button class="card-action" data-action="work">Work today</button></div><div class="progress-track"><span style="width:${state.project.progress}%"></span></div></div>`:`<div class="content-grid">${[{name:'Starlit Harbor',genre:'Cozy simulation',platform:'PC',budget:9000,icon:'✿',desc:'Build a little harbor town, one friendship at a time.'},{name:'Neon Courier',genre:'Arcade action',platform:'PC',budget:10500,icon:'↗',desc:'Race the clock through a neon-soaked future city.'},{name:'Pocket Planet',genre:'Puzzle adventure',platform:'Mobile',budget:8000,icon:'◎',desc:'Solve charming cosmic puzzles on a tiny planet.'}].map(p=>`<article class="content-card"><div class="card-icon">${p.icon}</div><h3>${p.name}</h3><span class="card-tag">${p.genre}</span><p>${p.desc}</p><div class="card-meta"><span>${p.platform} · ${fmt(p.budget)} budget</span><span>${state.team.length} teammates</span></div><button class="card-action" data-project="${p.name}" data-genre="${p.genre}" data-platform="${p.platform}" data-budget="${p.budget}">Start this game →</button></article>`).join('')}</div>`}${state.games.length?`<div class="wide-panel" style="margin-top:14px"><h2>Released games</h2>${state.games.map(g=>`<div class="employee-row"><div class="card-icon">★</div><div class="employee-info"><strong>${escapeHtml(g.name)}</strong><small>${escapeHtml(g.genre)} · Released ${escapeHtml(g.released)}</small></div><span class="card-tag">${g.quality}% player rating</span></div>`).join('')}</div>`:''}`;
  const teamView=()=>`<div class="view-heading"><div><div class="eyebrow">GOOD PEOPLE MAKE GREAT GAMES</div><h1>Your team</h1><p>Build a balanced team and keep your creative energy flowing.</p></div><span class="card-tag">${state.team.length} TEAM MEMBERS</span></div><div class="wide-panel"><h2>Studio roster <span style="color:#96a199;font-size:10px;font-weight:400">· ${fmt(state.team.reduce((n,p)=>n+p.salary,0))}/day payroll</span></h2>${state.team.map((p,i)=>`<div class="employee-row"><div class="employee-avatar">${escapeHtml(p.initials||p.name.slice(0,2).toUpperCase())}</div><div class="employee-info"><strong>${escapeHtml(p.name)}</strong><small>${escapeHtml(p.role)} · ${i===state.team.length-1&&p.salary===0?'Founder':'Studio team'}</small></div><span class="employee-skill">✦ ${Math.round(p.skill)} skill</span><span class="salary">${p.salary?fmt(p.salary)+'/day':'Founder'}</span></div>`).join('')}</div><div class="view-heading" style="margin:20px 0 12px"><div><h2 style="font:600 16px 'Space Grotesk';margin:0">Meet your next teammate</h2><p style="margin-top:5px">A one-time signing bonus equal to one week of salary.</p></div></div><div class="content-grid">${[{role:'Designer',desc:'Shapes the feel and fun of every game.',cost:90*7,icon:'✿'},{role:'Programmer',desc:'Turns your big ideas into playable worlds.',cost:120*7,icon:'⌘'},{role:'Artist',desc:'Gives your games their own visual soul.',cost:85*7,icon:'◉'},{role:'Producer',desc:'Keeps your team focused and projects on track.',cost:105*7,icon:'◷'},{role:'Marketer',desc:'Helps the right players discover your games.',cost:95*7,icon:'↗'}].map(x=>`<article class="content-card"><div class="card-icon">${x.icon}</div><h3>${x.role}</h3><p>${x.desc}</p><div class="card-meta"><span>${fmt(x.cost)} signing bonus</span><span>${fmt(x.cost/7)}/day</span></div><button class="card-action" data-hire="${x.role}">Invite to studio →</button></article>`).join('')}</div>`;
